    ('<!-- ===== 新用户绑定设备 · 首次设置：修改以下文字即可 ===== -->', '<!-- ===== New-user device binding · First-time setup: Edit text below ===== -->'),
    ('<h2>新用户绑定设备 · 首次设置</h2>', '<h2>New-user device binding · First-time setup</h2>'),
