count = 0
miss = 0
for old, new in repls:
    n = t.count(old)
    if n == 0:
        miss += 1
        print('MISS: ' + old[:90])
    else:
        t = t.replace(old, new)
        count += n
        print('{:4d}x  {}'.format(n, old[:60]))

with open('index.html', 'w', encoding='utf-8') as f:
    f.write(t)

print('\nBatch 4 done: {} replacements, {} missed'.format(count, miss))
